// Compile the ADO PR create body from the portable payload.
const repos = $input.first().json.value || [];
const incoming = $('Webhook - pr-create').item.json.body || $('Webhook - pr-create').item.json;

const repoName = incoming.repo || 'app';
const repo = repos.find(r => r.name === repoName);
if (!repo) throw new Error(`repo '${repoName}' not found in ADO project`);

const body = {
  sourceRefName: `refs/heads/${incoming.source}`,
  targetRefName: `refs/heads/${incoming.target}`,
  title: incoming.title,
  description: incoming.description || '',
  isDraft: Boolean(incoming.draft)
};

return [{ json: {
  body,
  repo_id: repo.id,
  repo_name: repoName,
  work_item: incoming.work_item || null,
  org: $env.AZDO_ORG_TRUSTWORKS || 'Trustworks',
  project: $env.AZDO_PROJECT_TRUSTWORKS || 'App'
}}];

const r = $input.first().json;
const status = r.statusCode || 0;
const ctx = $('Compile ADO PR body').item.json;

if (status >= 200 && status < 300) {
  const pr = r.body || r;
  const url = `https://dev.azure.com/${ctx.org}/${ctx.project}/_git/${ctx.repo_name}/pullrequest/${pr.pullRequestId}`;
  return [{ json: { status: 200, id: pr.pullRequestId, url, repo: ctx.repo_name, work_item: ctx.work_item } }];
}

let excerpt = '';
try { excerpt = typeof r.body === 'string' ? r.body : JSON.stringify(r.body); } catch(e) {}
if (excerpt.length > 500) excerpt = excerpt.slice(0, 500) + '...';
return [{ json: { status: 502, error: 'upstream-ado', upstream_status: status, upstream_excerpt: excerpt } }];
